(cb: (event: string, payload?: unknown) => void): (() => void) => {
    const wrap = (channel: string) => (_e: IpcRendererEvent, payload?: unknown) =>
      cb(channel.replace(/^menu:/, ""), payload);
    const channels = [
      "menu:add-project",
      "menu:open-recent",
      "menu:find",
      "menu:palette",
      "menu:toggle-sidebar",
      "menu:toggle-inspector",
      "menu:new-window",
    ];
    const handlers = channels.map((c) => {
      const h = wrap(c);
      ipcRenderer.on(c, h);
      return { c, h };
    });
    return () => {
      handlers.forEach(({ c, h }) => ipcRenderer.removeListener(c, h));
    };
  }

(evt, payload) => {
      switch (evt) {
        case "add-project":
          void handleAddProject();
          break;
        case "open-recent": {
          const p = payload as { path: string; name: string } | undefined;
          if (!p) return;
          unmarkProjectPathRemoved(p.path);
          const existing = projects.find((project) => project.path === p.path);
          if (existing) setActiveProjectId(existing.id);
          else {
            void window.codeshell.projectRegistry.list().then((registry) => {
              const target = registry
                .map(trackedProjectFromRegistry)
                .find((project) => project.path === p.path);
              if (!target) return;
              setProjects((prev) => reconcileProjectsFromDiskWithRemap(registry, prev).projects);
              setActiveProjectId(target.id);
              setSessionIndices((prev) =>
                prev[target.id] ? prev : { ...prev, [target.id]: loadSessionIndex(target.id) },
              );
            });
          }
          break;
        }
        case "find":
          navigateFromSidebar(() => setSearchOpen(true));
          break;
        case "palette":
          navigateFromSidebar(() => setPaletteOpen(true));
          break;
        case "toggle-sidebar":
          toggleSidebar();
          break;
        case "toggle-inspector":
          // no-op: inspector panel removed
          break;
        case "new-window":
          void window.codeshell.newWindow();
          break;
      }
    }
